import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.em2JOrjF.js";const p=JSON.parse('{"title":"Time Off Requests","description":"","frontmatter":{},"headers":[],"relativePath":"reference/workflows/time-off.md","filePath":"reference/workflows/time-off.md"}'),n={name:"reference/workflows/time-off.md"};function s(i,e,l,d,c,u){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="time-off-requests" tabindex="-1">Time Off Requests <a class="header-anchor" href="#time-off-requests" aria-label="Permalink to &quot;Time Off Requests&quot;">​</a></h1><p>The request-and-approval workflow for PTO, sick time, and leave.</p><hr><h2 id="three-types-of-time-off" tabindex="-1">Three types of time off <a class="header-anchor" href="#three-types-of-time-off" aria-label="Permalink to &quot;Three types of time off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Description</th><th>Typical use</th></tr></thead><tbody><tr><td><strong>PTO</strong></td><td>Paid time off / vacation</td><td>Planned holidays, vacation days</td></tr><tr><td><strong>Sick</strong></td><td>Sick days</td><td>Unexpected illness</td></tr><tr><td><strong>Leave</strong></td><td>Unpaid or extended leave</td><td>Parental leave, sabbatical, extended absence</td></tr></tbody></table><hr><h2 id="the-core-rule" tabindex="-1">The core rule <a class="header-anchor" href="#the-core-rule" aria-label="Permalink to &quot;The core rule&quot;">​</a></h2><p><strong>Users cannot log time directly to Out of Office, Sick, or Leave projects.</strong> Time is only recorded there after an approval — or when a Manager logs it directly using <code>log_sick_day</code> or <code>log_leave</code>.</p><hr><h2 id="requesting-time-off-user" tabindex="-1">Requesting time off (User) <a class="header-anchor" href="#requesting-time-off-user" aria-label="Permalink to &quot;Requesting time off (User)&quot;">​</a></h2><p>Any active user can request their own time off:</p><blockquote><p>&quot;I want to take March 20 off&quot; &quot;Can I book PTO for next Friday?&quot; &quot;I need sick time on Tuesday&quot;</p></blockquote><p>VERA creates a pending request in <code>10. Pending_PTO</code> and <strong>sends a Slack DM to all Managers and Owners</strong>. Time is not logged yet.</p><p>VERA confirms:</p><blockquote><p>&quot;Your PTO request for March 20 has been submitted. Your manager has been notified and will confirm.&quot;</p></blockquote><hr><h2 id="approving-a-request-manager-owner" tabindex="-1">Approving a request (Manager/Owner) <a class="header-anchor" href="#approving-a-request-manager-owner" aria-label="Permalink to &quot;Approving a request (Manager/Owner)&quot;">​</a></h2><p>Managers receive a DM. To approve:</p><blockquote><p>&quot;Approve time off request #8&quot; &quot;Approve Alice&#39;s PTO&quot;</p></blockquote><p>VERA:</p><ol><li>Logs the time entry to the Out of Office project</li><li>Updates the pending request to <code>&quot;approved&quot;</code></li><li>Notifies the user via DM</li></ol><hr><h2 id="rejecting-a-request" tabindex="-1">Rejecting a request <a class="header-anchor" href="#rejecting-a-request" aria-label="Permalink to &quot;Rejecting a request&quot;">​</a></h2><blockquote><p>&quot;Reject request #8&quot; &quot;Reject Alice&#39;s PTO — we&#39;re understaffed that week&quot;</p></blockquote><p>VERA updates the request to <code>&quot;rejected&quot;</code> and (optionally) passes the reason to the user.</p><hr><h2 id="viewing-pending-requests-manager-owner" tabindex="-1">Viewing pending requests (Manager/Owner) <a class="header-anchor" href="#viewing-pending-requests-manager-owner" aria-label="Permalink to &quot;Viewing pending requests (Manager/Owner)&quot;">​</a></h2><blockquote><p>&quot;Show pending time off requests&quot; &quot;What PTO is waiting for approval?&quot;</p></blockquote><p><code>list_pending_pto</code> shows all unresolved requests. Managers see requests for their team; Owners see all.</p><hr><h2 id="viewing-own-time-off-history-user" tabindex="-1">Viewing own time off history (User) <a class="header-anchor" href="#viewing-own-time-off-history-user" aria-label="Permalink to &quot;Viewing own time off history (User)&quot;">​</a></h2><blockquote><p>&quot;How much PTO have I taken this year?&quot; &quot;Show my sick days&quot; &quot;What leave do I have?&quot;</p></blockquote><p><code>get_my_time_off</code> returns the user&#39;s own history, filtered by type and date range if needed.</p><hr><h2 id="manager-direct-logging-sick-day" tabindex="-1">Manager direct logging (sick day) <a class="header-anchor" href="#manager-direct-logging-sick-day" aria-label="Permalink to &quot;Manager direct logging (sick day)&quot;">​</a></h2><p>For unexpected absences, Managers can log a sick day directly — no approval flow:</p><blockquote><p>&quot;Mark Sarah as sick today&quot; &quot;Log a sick day for @bob on March 15&quot;</p></blockquote><p>This creates the time entry immediately and creates an Unresolved Item if the person has active project envelopes (flagging the commitment conflict for the Manager to address).</p><p>Managers cannot use this tool for themselves — only Owners can log sick time for a Manager.</p><hr><h2 id="manager-direct-logging-leave" tabindex="-1">Manager direct logging (leave) <a class="header-anchor" href="#manager-direct-logging-leave" aria-label="Permalink to &quot;Manager direct logging (leave)&quot;">​</a></h2><p>For extended absences, Managers use <code>log_leave</code> with a date range:</p><blockquote><p>&quot;Put Alex on leave from March 3 to April 11&quot; &quot;Log parental leave for @carol — April through July&quot;</p></blockquote><p>VERA automatically skips weekends and company holidays within the date range.</p><hr><h2 id="unresolved-items-from-time-off" tabindex="-1">Unresolved items from time off <a class="header-anchor" href="#unresolved-items-from-time-off" aria-label="Permalink to &quot;Unresolved items from time off&quot;">​</a></h2><p>When sick time or leave is logged for someone who has active project envelopes, VERA automatically creates an Unresolved Item flagging the commitment conflict. The Manager sees this in the morning summary as a 🔴 block.</p><p>To handle the conflict:</p><blockquote><p>&quot;What should I do about item #3?&quot;</p></blockquote><p><code>get_resolution_options</code> returns ranked options (e.g. reassign the work, cancel the envelope, dismiss the conflict). The Manager chooses and VERA executes.</p><hr><h2 id="company-holidays" tabindex="-1">Company holidays <a class="header-anchor" href="#company-holidays" aria-label="Permalink to &quot;Company holidays&quot;">​</a></h2><p>Add holidays to exclude them from leave date calculations:</p><blockquote><p>&quot;Add Christmas as a company holiday on December 25&quot; &quot;What holidays do we have?&quot; &quot;Remove the summer offsite holiday&quot;</p></blockquote><p>Only Owners can manage the company calendar.</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User: request_time_off → Pending_PTO row created, Managers DM&#39;d</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>Manager: approve_time_off → Time entry logged + Pending_PTO updated + User DM&#39;d</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>          (if envelope conflicts exist) → Unresolved_Item created → resolve or dismiss</span></span></code></pre></div>`,58)])])}const f=a(n,[["render",s]]);export{p as __pageData,f as default};
